import pandas as pd
import os
import numpy as np
import ast
def task_func(directory):
    csv_files = []
    try:
        for name in os.listdir(directory):
            full = os.path.join(directory, name)
            if os.path.isfile(full) and name.lower().endswith('.csv'):
                csv_files.append((name, full))
    except Exception:
        csv_files = []
    if not csv_files:
        df_empty = pd.DataFrame(columns=['email', 'list', 'sum', 'mean', 'median'])
        return df_empty, None
    longest = max(csv_files, key=lambda x: len(x[0]))
    df = pd.read_csv(longest[1])
    if 'email' not in df.columns or 'list' not in df.columns:
        df = pd.DataFrame(columns=['email', 'list'])
    def parse_list(x):
        if isinstance(x, str):
            try:
                v = ast.literal_eval(x)
                if isinstance(v, (list, tuple, np.ndarray)):
                    return list(v)
                return np.nan
            except Exception:
                return np.nan
        if isinstance(x, (list, tuple, np.ndarray)):
            return list(x)
        return np.nan
    df['list'] = df['list'].apply(parse_list) if 'list' in df.columns else []
    def compute_sum(v):
        try:
            arr = np.array(v, dtype=float)
            return float(np.nansum(arr)) if arr.size > 0 else np.nan
        except Exception:
            return np.nan
    def compute_mean(v):
        try:
            arr = np.array(v, dtype=float)
            return float(np.nanmean(arr)) if arr.size > 0 else np.nan
        except Exception:
            return np.nan
    def compute_median(v):
        try:
            arr = np.array(v, dtype=float)
            return float(np.nanmedian(arr)) if arr.size > 0 else np.nan
        except Exception:
            return np.nan
    df['sum'] = df['list'].apply(compute_sum)
    df['mean'] = df['list'].apply(compute_mean)
    df['median'] = df['list'].apply(compute_median)
    med = df['median'].dropna() if 'median' in df.columns else pd.Series(dtype=float)
    ax = None
    if len(med) > 0:
        import matplotlib.pyplot as plt
        ax = med.plot(kind='hist')
    return df[['email', 'list', 'sum', 'mean', 'median']] if set(['email','list']).issubset(df.columns) else df, ax
