    if not os.path.isdir(directory):
        df_empty = pd.DataFrame(columns=['email', 'list', 'sum', 'mean', 'median'])
        return df_empty, None
    entries = []
    try:
        for name in os.listdir(directory):
            path = os.path.join(directory, name)
            if os.path.isfile(path) and name.lower().endswith('.csv'):
                entries.append(path)
    except Exception:
        entries = []
    if not entries:
        df_empty = pd.DataFrame(columns=['email', 'list', 'sum', 'mean', 'median'])
        return df_empty, None
    target = max(entries, key=lambda p: len(os.path.basename(p)))
    df = pd.read_csv(target)
    def parse_list(x):
        try:
            return ast.literal_eval(x) if isinstance(x, str) else x
        except Exception:
